/* Science / Sources page (public): what comes from NASA OSDR (OSD-575, OSD-656, OSD-53) and NASA DONKI,
 * and how it is used. Data: window.ASTRA_NASA (js/nasa-reference.js, generated by
 * scripts/build_nasa_reference.py) and GET /api/space-weather/. */
(function () {
  'use strict';
  var A = Astra, N = window.ASTRA_NASA;
  A.init('science');
  var $ = function (id) { return document.getElementById(id); };
  var fmt = function (v) { return v === null || v === undefined ? '—' : String(v); };

  if (!N) { $('studies').innerHTML = '<p class="empty">js/nasa-reference.js is missing. Run scripts/build_nasa_reference.py.</p>'; }
  else {
    $('ref-gen').textContent = 'built ' + N.generated_at.slice(0, 10);
    $('studies').innerHTML = ['OSD-575', 'OSD-656', 'OSD-53'].map(function (id) {
      var s = N.studies[id];
      return '<article class="study"><div class="study-id">' + id + '</div><h3>' + A.esc(s.title) + '</h3>' +
        '<p class="dim">' + A.esc(s.design) + ' · released ' + A.esc(s.release_date) + '</p>' +
        '<p class="study-use"><b>Used for:</b> ' + ({
          'OSD-575': 'serum lab bands (cytokines, CRP, calcium, albumin, glucose) and the immune scenario shift',
          'OSD-656': 'urine inflammation bands (IL-6, IL-8, MPO, NGAL)',
          'OSD-53': 'gene context on the Immune risk card'
        })[id] + '</p>' +
        '<ul class="study-files">' + s.files.map(function (f) { return '<li><a href="' + A.esc(f.url) + '" target="_blank" rel="noopener">' + A.esc(f.name) + '</a></li>'; }).join('') + '</ul>' +
        '<p class="dim" style="font-size:12px">' + (s.publications || []).map(function (p) { return A.esc(p.title) + (p.doi ? ' · <a href="https://doi.org/' + A.esc(p.doi) + '" target="_blank" rel="noopener">doi:' + A.esc(p.doi) + '</a>' : ''); }).join('<br>') + '</p>' +
        '<a class="btn btn-sm" href="' + A.esc(s.url) + '" target="_blank" rel="noopener">Open ' + id + ' on OSDR ↗</a></article>';
    }).join('');

    $('bands').innerHTML = '<thead><tr><th>Marker</th><th>Study</th><th>Pre-flight mean ± SD</th><th>Return day (R+1)</th><th>Change</th><th>Crew</th><th>Green</th><th>Yellow</th><th>Red</th><th>Recovery (R+45 / R+82)</th></tr></thead><tbody>' +
      N.monitoring.map(function (m) {
        var up = m.direction === 'up', c = up ? '≥ ' : '≤ ', rec = m.recovery || {};
        return '<tr><td><b>' + A.esc(m.label) + '</b><small class="dim">' + A.esc(m.meaning) + ' · ' + A.esc(m.unit) + '</small></td><td>' + m.study + '</td>' +
          '<td class="num">' + fmt(m.preflight_mean) + ' ± ' + fmt(m.preflight_sd) + ' <span class="dim">(n=' + m.preflight_n + ')</span></td>' +
          '<td class="num">' + fmt(m.yellow_at) + ' <span class="dim">(n=' + m.return_n + ')</span></td>' +
          '<td class="num">' + (up ? '↑' : '↓') + ' ×' + m.fold_change + '</td><td>' + m.crew + '</td>' +
          '<td class="num st-green">' + fmt(m.green[0]) + '–' + fmt(m.green[1]) + '</td><td class="num st-yellow">' + c + fmt(m.yellow_at) + '</td><td class="num st-red">' + c + fmt(m.red_at) + '</td>' +
          '<td class="num dim">' + fmt(rec['R+45']) + ' / ' + fmt(rec['R+82']) + '</td></tr>';
      }).join('') + '</tbody>';

    var bars = (N.shifted['OSD-575'] || []).concat((N.shifted['OSD-656'] || []).slice(0, 8));
    var maxL = Math.max.apply(null, bars.map(function (b) { return Math.abs(b.log2_fc); }));
    $('fc-bars').innerHTML = bars.map(function (b) {
      return '<div class="fc-row"><span class="fc-name" title="' + A.esc(b.marker) + '">' + A.esc(b.marker) + ' <small class="dim">' + b.study + '</small></span>' +
        '<span class="fc-bar"><i class="' + (b.study === 'OSD-656' ? 'urine' : 'serum') + '" style="width:' + (Math.abs(b.log2_fc) / maxL * 100).toFixed(1) + '%"></i></span>' +
        '<b class="mono">×' + b.fold_change + '</b></div>';
    }).join('');

    $('genes').innerHTML = '<thead><tr><th>Gene</th><th>What it does</th><th>Landing vs. pre-flight</th><th>p</th><th>Astronauts</th></tr></thead><tbody>' +
      (N.shifted['OSD-53'] || []).map(function (g) {
        return '<tr><td><b>' + A.esc(g.marker) + '</b></td><td class="dim" style="font-size:12.5px">' + A.esc(g.name) + '</td><td class="num">' + (g.direction === 'up' ? '↑' : '↓') + ' ×' + g.fold_change + '</td><td class="num">' + g.p_value + '</td><td class="dim">' + A.esc(g.astronauts) + '</td></tr>';
      }).join('') + '</tbody>';
  }

  Api.getSpaceWeather().then(function (d) {
    AstraSpaceWeather.render($('sw-body'), d);
    var c = d.counts || {};
    $('sw-counts').innerHTML = 'Events available: ' + (c.FLR || 0) + ' flares (M/X), ' + (c.SEP || 0) + ' SEP records, ' + (c.CME || 0) + ' CMEs, ' + (c.GST || 0) + ' geomagnetic storms' +
      (d.snapshot_fetched_at ? ' · bundled snapshot fetched ' + A.esc(d.snapshot_fetched_at.slice(0, 10)) : '') + '.';
  }).catch(function (e) { $('sw-body').innerHTML = '<p class="empty">Space weather unavailable: ' + A.esc(e.message) + '</p>'; });
  A.reveal(document);
})();
